sql.where:
e.status = 'PUBLISHED'

    AND (
        LOWER(e.name) LIKE CONCAT('%', LOWER(#{query.search}), '%')
        OR LOWER(COALESCE(e.description, '')) LIKE CONCAT('%', LOWER(#{query.search}), '%')
        OR LOWER(v.name) LIKE CONCAT('%', LOWER(#{query.search}), '%')
        OR LOWER(v.city) LIKE CONCAT('%', LOWER(#{query.search}), '%')
    )


    AND e.venue_id = #{query.venueId}


    AND e.start_time >= #{query.startDate}


    AND e.start_time <= #{query.endDate}

mapper.select:
SELECT

FROM events
ORDER BY start_time ASC, name ASC, id ASC
LIMIT #{limit}
OFFSET #{offset}
